/**
 * GENERATED by web/scripts/gen-android-learn.mjs from web/src/app/learn and
 * web/src/data. Do not edit; run
 * `cd web && node scripts/gen-android-learn.mjs`.
 *
 * The seven Learn sections, as blocks. The prose is the web surface's, read
 * out of the pages rather than retyped, so an explainer edited once is
 * edited on both surfaces.
 *
 * Where a page's body is a table driven by a data module, the table travels
 * as data too and the screen renders it after the prose. The one thing that
 * does not cross is the sample chart wheel on the hub, which the day screen
 * already draws from a real chart.
 */
sealed interface LearnBlock {
    /** The page head: a mono kicker over a display headline. */
    data class Head(val kicker: String, val headline: String) : LearnBlock

    /** A rule with a caption set into it. */
    data class Divider(val label: String) : LearnBlock

    /** A section heading inside the page. */
    data class Heading(val text: String) : LearnBlock

    /** One paragraph of prose. */
    data class Para(val text: String) : LearnBlock
}

/** A table a section renders from reference data after its prose. */
enum class LearnTable { PLANET_VERBS, ZODIAC_SIGNS, HOUSES, HOUSE_SYSTEMS, ASPECTS }

data class LearnSection(
    val n: Int,
    val title: String,
    val href: String,
    val blurb: String,
    val blocks: List<LearnBlock>,
    val table: LearnTable?,
)

/** One of the twelve, as the signs page prints it. */
data class ZodiacSignInfo(
    val sign: String,
    val symbol: String,
    val dates: String,
    val element: String,
    val modality: String,
    val traits: String,
    val blurb: String,
)

/** A body and the verb the hub gives it: the grammar under a placement. */
data class PlanetVerb(val symbol: String, val name: String, val verb: String)

/** One way of cutting the sky into twelve, and whether this app uses it. */
data class HouseSystem(
    val name: String,
    val age: String,
    val body: String,
    val ours: Boolean,
)

/** The pure geometry of an aspect, culture-neutral. */
fun aspectGeometry(aspect: AspectType): String = when (aspect) {
    AspectType.CONJUNCTION -> "Same point in the sky; the two forces fuse and read as one."
    AspectType.SEXTILE -> "Sixty degrees apart, a third of a square; an opening, not a guarantee."
    AspectType.SQUARE -> "Ninety degrees apart, a right angle; friction, and a forced choice."
    AspectType.TRINE -> "A hundred twenty degrees, a third of the circle; the easiest geometry there is."
    AspectType.OPPOSITION -> "A hundred eighty degrees, the two ends of one line; a mirror, not an enemy."
}

/**
 * One institutional ruling per aspect per culture: Rome's augury, Egypt's
 * weighing, Greece's oracle, Canaan's council, Carthage's ledger. These
 * describe the KIND, which is what a glossary is for; the figure-tethered
 * rulings the readings use are in ReadingBanks.
 */
fun aspectRuling(culture: AncientCulture, aspect: AspectType): String = when (culture) {
    AncientCulture.EGYPT -> when (aspect) {
        AspectType.CONJUNCTION -> "Two gods ride in one barque. Where the river carries it, it carries them both."
        AspectType.SEXTILE -> "A fair wind stands on the river. It moves only the boat that raises a sail."
        AspectType.SQUARE -> "Isfet crossed the threshold of the hall. The pans come level again through labor, and the labor is yours."
        AspectType.TRINE -> "Heart and feather agree and no hand touches the scale. Go on with the day; the hall asks you nothing."
        AspectType.OPPOSITION -> "The two pans hang level, and neither falls. The scribe writes no verdict until one side descends."
    }

    AncientCulture.GREECE -> when (aspect) {
        AspectType.CONJUNCTION -> "The tripod answers once for two gods. Nothing in the answer belongs to one more than the other."
        AspectType.SEXTILE -> "The shrine takes questions today. An unasked god has nothing to say to you."
        AspectType.SQUARE -> "The price is named before the answer, and it is not small. Pay it, or ask nothing."
        AspectType.TRINE -> "The oracle speaks before the question is finished. The god volunteered the answer."
        AspectType.OPPOSITION -> "Delphi says one thing and Dodona the other. Both answers are true, and acting on one breaks the other."
    }

    AncientCulture.CANAAN -> when (aspect) {
        AspectType.CONJUNCTION -> "The docket carries two names under a single heading. Whatever El decrees falls on the pair."
        AspectType.SEXTILE -> "Nothing reaches the council but by vow. Silence keeps the matter off the list."
        AspectType.SQUARE -> "A witness rises against the matter. Nothing passes at this sitting that is not spoken against first."
        AspectType.TRINE -> "No vow was made and the rains came anyway. The wadis are running full."
        AspectType.OPPOSITION -> "Baal holds above and Mot holds below. El hears both and decrees nothing."
    }

    AncientCulture.CARTHAGE -> when (aspect) {
        AspectType.CONJUNCTION -> "One manifest covers two cargoes. Profit or loss, the ledger no longer tells them apart."
        AspectType.SEXTILE -> "The harbor is open and a berth is held in your name. Nothing loads itself."
        AspectType.SQUARE -> "Short weight turns up in the audit. Trade goes on, and a clerk watches every measure you make."
        AspectType.TRINE -> "The sailing season opens and the ledger is clean. Nothing stands against your name in the precinct."
        AspectType.OPPOSITION -> "Two merchants claim one cargo at the quay. The hold stays sealed and the season runs on without it."
    }

    AncientCulture.ROME -> when (aspect) {
        AspectType.CONJUNCTION -> "The auspice was taken once and it binds two names. Neither can act on it alone."
        AspectType.SEXTILE -> "The birds are favorable and no one has yet taken the auspice. A sign unclaimed confers no right to act."
        AspectType.SQUARE -> "An objection is entered and the objector has standing. Every step of this goes forward under challenge."
        AspectType.TRINE -> "The day stands fastus and the augury attached no condition. What is done under it holds."
        AspectType.OPPOSITION -> "Two magistrates, one office. Each vetoes the other, and the day's business stands adjourned."
    }
}

